#include "../Source/PluginProcessor.h"
#include "../Source/PluginEditor.h"
#include <juce_audio_utils/juce_audio_utils.h>
#include <iostream>
#include <stdexcept>
void check(bool x,const char* m){if(!x)throw std::runtime_error(m);}
void set(EQP1AProcessor& p,const char* id,float x){auto* a=p.apvts.getParameter(id);check(a!=nullptr,"parameter exists");a->setValueNotifyingHost(a->convertTo0to1(x));}
juce::Slider* findKnob(juce::Component& root,const juce::String& name){if(auto* slider=dynamic_cast<juce::Slider*>(&root))if(slider->getName()==name)return slider;for(auto* child:root.getChildren())if(auto* found=findKnob(*child,name))return found;return nullptr;}
juce::Label* valueLabel(juce::Slider& slider){for(auto* child:slider.getChildren())if(auto* label=dynamic_cast<juce::Label*>(child))return label;return nullptr;}
void enterValue(juce::Component& root,const char* knobName,const char* text,bool viaLabel=false,bool cancel=false){auto* slider=findKnob(root,knobName);check(slider!=nullptr,"editable knob exists");auto* label=valueLabel(*slider);check(label&&label->isEditableOnDoubleClick()&&!label->isEditableOnSingleClick(),"value label edits on double click");auto* target=viaLabel?static_cast<juce::Component*>(label):static_cast<juce::Component*>(slider);auto now=juce::Time::getCurrentTime();juce::MouseEvent event(juce::Desktop::getInstance().getMainMouseSource(),{1.f,1.f},juce::ModifierKeys(),0,0,0,0,0,target,target,now,{1.f,1.f},now,2,false);target->mouseDoubleClick(event);auto* editor=label->getCurrentTextEditor();check(editor!=nullptr,"double click opens numeric editor");editor->setText(text,false);slider->hideTextBox(cancel);}
struct Result{double level;std::array<double,4> spectrum;};
Result measure(EQP1AProcessor& p,double sr){p.prepareToPlay(sr,128);juce::AudioBuffer<float>b(2,128);juce::MidiBuffer m;double ei=0,eo=0,re[4]{},im[4]{};constexpr double hz[]={30,1000,4000,8000};int total=int(sr*3),start=int(sr*2);for(int k=0;k<total;k+=128){int size=juce::jmin(128,total-k);b.setSize(2,size,false,false,true);for(int i=0;i<size;++i){double x=0;for(double f:hz)x+=.025*std::sin(juce::MathConstants<double>::twoPi*f*(k+i)/sr);b.setSample(0,i,float(x));b.setSample(1,i,float(x));}if(k>=start)for(int i=0;i<size;++i)ei+=double(b.getSample(0,i))*b.getSample(0,i);p.processBlock(b,m);for(int i=0;i<size;++i){double x=b.getSample(0,i);check(std::isfinite(x),"finite audio");check(x==b.getSample(1,i),"stereo linked");if(k>=start){eo+=x*x;for(int j=0;j<4;++j){double ph=juce::MathConstants<double>::twoPi*hz[j]*(k+i)/sr;re[j]+=x*std::cos(ph);im[j]+=x*std::sin(ph);}}}}Result r;r.level=10*std::log10(eo/ei);for(int j=0;j<4;++j)r.spectrum[j]=std::hypot(re[j],im[j]);return r;}
double ratio(const Result& r,int a,int b){return 20*std::log10(r.spectrum[a]/r.spectrum[b]);}
int main(int argc,char** argv){juce::ScopedJuceInitialiser_GUI init;try{
 for(double sr:{44100.,48000.,96000.,192000.}){EQP1AProcessor p;auto flat=measure(p,sr);check(std::abs(flat.level)<.03,"neutral unity");set(p,"lowBoost",7);auto boost=measure(p,sr);check(ratio(boost,0,1)>4,"low boost shape");check(std::abs(boost.level)<.15,"automatic RMS match low boost");set(p,"fix",0);auto uncompensated=measure(p,sr);check(uncompensated.level>2,"FIX off retains EQ gain");set(p,"fix",1);set(p,"lowAtten",7);auto combo=measure(p,sr);check(std::abs(ratio(combo,0,1)-15.377)<.15,"UADx simultaneous low boost/cut shape");set(p,"power",0);check(std::abs(measure(p,sr).level)<.03,"power bypass");set(p,"power",1);set(p,"lowBoost",0);set(p,"lowAtten",0);set(p,"highBoost",7);auto high=measure(p,sr);check(ratio(high,3,1)>5,"high boost shape");check(std::abs(high.level)<.15,"automatic RMS match high boost");set(p,"bandwidth",0);auto narrow=measure(p,sr);set(p,"bandwidth",10);auto broad=measure(p,sr);check(ratio(broad,2,3)>ratio(narrow,2,3)+2,"bandwidth sharp to broad");set(p,"highBoost",0);set(p,"highAtten",10);auto cut=measure(p,sr);check(ratio(cut,3,1)<-2,"high attenuation shape");check(std::abs(cut.level)<.15,"automatic RMS match cut");for(int step=0;step<22;++step){set(p,"highFreq",float(step));set(p,"highBoost",10);auto extreme=measure(p,sr);check(std::abs(extreme.level)<.25,"RMS match every high step");}std::cout<<"PASS DSP, bandwidth, RMS match and all high steps at "<<sr<<" Hz\n";}
 EQP1AProcessor linearA,linearB;for(auto* processor:{&linearA,&linearB}){set(*processor,"fix",0);set(*processor,"lowBoost",7);set(*processor,"lowAtten",4);set(*processor,"highBoost",6);processor->prepareToPlay(48000,128);}juce::AudioBuffer<float> a(2,128),b(2,128);juce::MidiBuffer midi;juce::Random rng(12345);for(int block=0;block<50;++block){for(int c=0;c<2;++c)for(int i=0;i<128;++i){float x=(rng.nextFloat()-.5f)*.1f;a.setSample(c,i,x);b.setSample(c,i,x*2);}linearA.processBlock(a,midi);linearB.processBlock(b,midi);for(int c=0;c<2;++c)for(int i=0;i<128;++i)check(std::abs(b.getSample(c,i)-2*a.getSample(c,i))<1e-6,"clean linear gain scaling with FIX off");}EQP1AProcessor silence;silence.prepareToPlay(48000,128);for(int block=0;block<100;++block){a.clear();silence.processBlock(a,midi);check(a.getMagnitude(0,a.getNumSamples())==0,"no generated noise on silence");}std::cout<<"PASS clean linear scaling and digital silence\n";
 EQP1AProcessor trim;set(trim,"lowBoost",7);set(trim,"highBoost",6);set(trim,"highAtten",5);auto matched=measure(trim,48000);check(std::abs(matched.level)<.15,"FIX at unity before output");set(trim,"output",6);auto louder=measure(trim,48000);check(std::abs(louder.level-matched.level-6)<.03,"output +6 dB after FIX is not cancelled");set(trim,"output",-6);auto quieter=measure(trim,48000);check(std::abs(quieter.level-matched.level+6)<.03,"output -6 dB after FIX is not cancelled");set(trim,"fix",0);set(trim,"output",0);auto raw=measure(trim,48000);set(trim,"output",6);auto rawTrim=measure(trim,48000);check(std::abs(rawTrim.level-raw.level-6)<.03,"output gain with FIX off");set(trim,"power",0);set(trim,"output",12);check(std::abs(measure(trim,48000).level)<.03,"Power bypass ignores output trim");juce::MemoryBlock trimState;trim.getStateInformation(trimState);EQP1AProcessor restored;restored.setStateInformation(trimState.getData(),int(trimState.getSize()));check(std::abs(restored.apvts.getRawParameterValue("output")->load()-12)<.01,"output state recall");std::cout<<"PASS OUTPUT after FIX: +6/-6 dB, FIX off, bypass and state\n";
 EQP1AProcessor p;check(p.apvts.getParameter("output")!=nullptr,"manual output control exists");set(p,"lowBoost",6.2f);juce::MemoryBlock state;p.getStateInformation(state);EQP1AProcessor q;q.setStateInformation(state.getData(),int(state.getSize()));check(std::abs(q.apvts.getRawParameterValue("lowBoost")->load()-6.2f)<.01,"state recall");
 auto* low=dynamic_cast<juce::AudioParameterChoice*>(p.apvts.getParameter("lowFreq"));auto* high=dynamic_cast<juce::AudioParameterChoice*>(p.apvts.getParameter("highFreq"));check(low&&low->choices.size()==9,"nine low steps");check(high&&high->choices.size()==22,"22 high steps");for(int i=0;i<9;++i)check(low->choices[i]==juce::String(20+10*i),"low step list");for(int i=0;i<22;++i)check(high->choices[i]==juce::String(i<20?i+1:i==20?30:40),"high step list");
 std::unique_ptr<juce::AudioProcessorEditor> e(p.createEditor());check(e->getWidth()==817&&e->getHeight()==126,"open at FET 67 minimum size");auto* limits=e->getConstrainer();check(limits&&limits->getMinimumWidth()==817&&limits->getMinimumHeight()==126&&limits->getMaximumWidth()==4085&&limits->getMaximumHeight()==630,"same resize limits as FET 67");check(std::abs(limits->getFixedAspectRatio()-1634./252)<1e-9,"same aspect ratio as FET 67");
 const char* knobNames[]={"Low Boost","Low Attenuation","Low Frequency","Bandwidth","High Boost","High Frequency","High Attenuation","Attenuation Frequency","Output"};const char* paramIds[]={"lowBoost","lowAtten","lowFreq","bandwidth","highBoost","highFreq","highAtten","attenFreq","output"};const char* inputs[]={"3,75","2.25","55 Hz","8.25","4.5","12000 Hz","6.75","17 kHz","-6,25 dB"};const float expected[]={3.75f,2.25f,4,8.25f,4.5f,11,6.75f,2,-6.25f};
 for(int i=0;i<9;++i){enterValue(*e,knobNames[i],inputs[i],i%2==1);check(std::abs(p.apvts.getRawParameterValue(paramIds[i])->load()-expected[i])<.02,"typed value reaches processor with correct units and snapping");}
 enterValue(*e,"High Frequency","27 kHz",true);check(p.apvts.getRawParameterValue("highFreq")->load()==20,"high selector snaps to 30 kHz");enterValue(*e,"Output","30");check(p.apvts.getRawParameterValue("output")->load()==12,"typed output clamps to limit");enterValue(*e,"Output","-8",true,true);check(p.apvts.getRawParameterValue("output")->load()==12,"Escape discards value edit");enterValue(*e,"Output","invalid");check(p.apvts.getRawParameterValue("output")->load()==12,"invalid text preserves current value");
 const float defaults[]={6.2f,0,4,5,0,7,0,1,0};for(int i=0;i<9;++i)set(p,paramIds[i],defaults[i]);e->setSize(4085,630);check(e->getWidth()==4085&&e->getHeight()==630,"maximum FET dimensions supported");e->setSize(1634,252);auto image=e->createComponentSnapshot(e->getLocalBounds());if(argc>1){juce::File out{juce::String(argv[1])};out.deleteFile();juce::FileOutputStream stream(out);juce::PNGImageFormat png;check(png.writeImageToStream(image,stream),"preview write");}e->setSize(2001,510);e.reset();e.reset(p.createEditor());check(e->getWidth()==817&&e->getHeight()==126,"reopen small after resize");std::cout<<"PASS FET67 resize dimensions, double-click numeric entry, units, snapping, cancel, state and editor render\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
